import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const configPath = path.expand('~/.config/stallion/cf-env');
const accountId = 'f496802dcadb597e5939f6449c759a43';

// Mask email: first char + *** + domain
function maskEmail(email) {
  const [local, domain] = email.split('@');
  return `${local[0]}***@${domain}`;
}

async function fetchApi(endpoint, token) {
  const response = await fetch(`https://api.cloudflare.com/client/v4${endpoint}`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  const data = await response.json();
  return { status: response.status, data };
}

// Read config file
let token;
try {
  const envContent = fs.readFileSync(configPath.replace('~', process.env.HOME), 'utf-8');
  const match = envContent.match(/CLOUDFLARE_API_TOKEN=[REDACTED]
  token = match ? match[1].trim() : null;
  if (!token) {
    console.error('❌ CLOUDFLARE_API_TOKEN not found in config');
    process.exit(1);
  }
} catch (err) {
  console.error('❌ Failed to read config:', err.message);
  process.exit(1);
}

console.log('📋 Cloudflare Access Audit\n');

// 1. Get Access apps
console.log('=== Apps ===');
const { data: appsRes } = await fetchApi(`/accounts/${accountId}/access/apps`, token);
if (!appsRes.success) {
  console.log('❌ Failed to fetch apps');
  process.exit(1);
}

let appId;
for (const app of appsRes.result) {
  if (app.domain.includes('stallion.matthijs-f49.workers.dev')) {
    appId = app.id;
    console.log(`ID: ${app.id}`);
    console.log(`Name: ${app.name}`);
    console.log(`Domain: ${app.domain}`);
    console.log(`Auto-redirect: ${app.auto_redirect_to_identity ?? 'N/A'}`);
    if (app.allowed_idps?.length) {
      console.log(`Allowed IDPs: ${app.allowed_idps.join(', ')}`);
    }
  }
}

if (!appId) {
  console.error('❌ stallion app not found');
  process.exit(1);
}

// 2. Get policies
console.log('\n=== Policies ===');
const { data: policiesRes } = await fetchApi(
  `/accounts/${accountId}/access/apps/${appId}/policies`,
  token
);
if (!policiesRes.success) {
  console.log('❌ Failed to fetch policies');
  process.exit(1);
}

for (const policy of policiesRes.result) {
  console.log(`\nPolicy: ${policy.name} | Decision: ${policy.decision}`);
  if (policy.include?.length) {
    for (const rule of policy.include) {
      if (rule.email) {
        console.log(`  - Email: ${maskEmail(rule.email)}`);
      } else if (rule.group) {
        console.log(`  - Group: ${rule.group.name}`);
      } else if (rule.email_domain) {
        console.log(`  - Email domain: ${rule.email_domain.domain}`);
      }
    }
  }
}

// 3. Get identity providers
console.log('\n=== Identity Providers ===');
const { data: idpRes } = await fetchApi(`/accounts/${accountId}/access/identity_providers`, token);
if (!idpRes.success) {
  console.log('❌ Failed to fetch IDPs');
  process.exit(1);
}

for (const idp of idpRes.result) {
  console.log(`${idp.type}: ${idp.name}`);
}

// 4. Get access logs
console.log('\n=== Recent Access Attempts ===');
const { status: logsStatus, data: logsRes } = await fetchApi(
  `/accounts/${accountId}/access/logs/access_requests?limit=25`,
  token
);
if (logsStatus === 403) {
  console.log(`❌ 403 Forbidden: ${logsRes.errors?.[0]?.message || 'No permission to access logs'}`);
} else if (!logsRes.success) {
  console.log('❌ Failed to fetch logs');
} else {
  const recentLogs = logsRes.result.slice(0, 10);
  for (const log of recentLogs) {
    const action = log.allowed ? '✓ Allowed' : '✗ Blocked';
    const userEmail = log.user_email ? maskEmail(log.user_email) : 'N/A';
    const country = log.ip_geo?.country || '';
    const idpInfo = log.idp_type || log.connection_type || 'N/A';
    console.log(
      `${log.created_at} | ${action} | ${log.app_domain} | ${userEmail} | ${country} | ${idpInfo}`
    );
  }
}

// 5. Get current user
console.log('\n=== Current User ===');
const { data: userRes } = await fetchApi(`/user`, token);
if (!userRes.success) {
  console.log('❌ Failed to fetch user info');
} else {
  console.log(`Email: ${maskEmail(userRes.result.email)}`);
}

