import os from 'os';

const configPath = path.join(os.homedir(), '.config/stallion/cf-env');
const accountId = 'f496802dcadb597e5939f6449c759a43';

// Read config
let token;
try {
  const envContent = fs.readFileSync(configPath, 'utf-8');
  const match = envContent.match(/CLOUDFLARE_API_TOKEN=[REDACTED]
  token = match ? match[1].trim() : null;
} catch (err) {
  console.error('Failed to read config:', err.message);
  process.exit(1);
}

async function fetchApi(endpoint, token) {
  const response = await fetch(`https://api.cloudflare.com/client/v4${endpoint}`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  return await response.json();
}

// Get app
const appsRes = await fetchApi(`/accounts/${accountId}/access/apps`, token);
const app = appsRes.result.find(a => a.domain.includes('stallion.matthijs-f49.workers.dev'));

// Get policies and print raw
const policiesRes = await fetchApi(`/accounts/${accountId}/access/apps/${app.id}/policies`, token);
for (const policy of policiesRes.result) {
  console.log(`\n=== Policy: ${policy.name} ===`);
  console.log(JSON.stringify(policy, null, 2));
}

